--
-- Table structure for table `question_settings`
--

DROP TABLE IF EXISTS `question_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `question_settings` (
  `id` int(11) NOT NULL COMMENT 'ID',
  `question_id` char(10) NOT NULL COMMENT '設問ID',
  `type_native_id` int(11) NOT NULL COMMENT '類型固有ID',
  `title` varchar(255) NOT NULL COMMENT '名称',
  `level` int(11) NOT NULL COMMENT '階層',
  `parent_question_id` int(11) DEFAULT NULL COMMENT '親階層ID',
  `parent_question_option_id` int(11) DEFAULT NULL,
  `input_method` int(11) NOT NULL COMMENT '入力方式',
  `score` int(11) NOT NULL COMMENT 'スコア',
  `disp_flg` tinyint(4) NOT NULL DEFAULT 0,
  `effective_date_flg` tinyint(4) NOT NULL,
  `required_flg` tinyint(4) NOT NULL,
  `terminal_flg` tinyint(4) NOT NULL,
  `viewing_check_flg` tinyint(4) NOT NULL DEFAULT 0,
  `update_date` datetime NOT NULL COMMENT '更新日',
  `registration_date` datetime NOT NULL COMMENT '登録日',
  `description` text NOT NULL,
  `duplicate_flg` tinyint(1) NOT NULL,
  `description_flg` tinyint(1) NOT NULL,
  `character_limit` int(11) NOT NULL,
  `interval_target_id` int(11) NOT NULL,
  `interval_month` int(11) NOT NULL,
  PRIMARY KEY (`id`,`question_id`,`type_native_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

